spec.expr:
(
  (
    xui_observatory_outbound_alive{job="xui-exporter",instance="${instance}"}
    * (1 + (xui_observatory_outbound_probe_failed_samples{job="xui-exporter",instance="${instance}"} == bool 0))
  )
  or (xui_observatory_outbound_alive{job="xui-exporter",instance="${instance}"} * 2)
)
and on (outbound)
max by (outbound) (
  xui_balancer_outbound_selected{job="xui-exporter",instance="${instance}",balancer=~"${balancer}",outbound!=""}
)

max by (instance, job) (
  xui_exporter_scrape_duration_seconds{
    job="xui-exporter",
    instance="${instance}",
    source=~"grpc|expvars"
  }
)

(100 * exp(
  -5 * (sum_over_time(xui_observatory_outbound_probe_failed_samples{job="xui-exporter",instance="${instance}"}[$__range]) / sum_over_time(xui_observatory_outbound_probe_samples{job="xui-exporter",instance="${instance}"}[$__range]))
  - 0.6 * (quantile_over_time(0.95, xui_observatory_outbound_rtt_mean_seconds{job="xui-exporter",instance="${instance}"}[$__range]) - quantile_over_time(0.50, xui_observatory_outbound_rtt_mean_seconds{job="xui-exporter",instance="${instance}"}[$__range]))
) * (clamp(130 - 100 * quantile_over_time(0.50, xui_observatory_outbound_rtt_mean_seconds{job="xui-exporter",instance="${instance}"}[$__range]), 0, 100) / 100) ^ 0.20)
and on (outbound) max by (outbound) (
  xui_balancer_outbound_selected{job="xui-exporter",instance="${instance}",balancer=~"${balancer}",outbound!=""}
)

((xui_observatory_outbound_alive{job="xui-exporter",instance="${instance}"} * (1 + (xui_observatory_outbound_probe_failed_samples{job="xui-exporter",instance="${instance}"} == bool 0)))
or (xui_observatory_outbound_alive{job="xui-exporter",instance="${instance}"} * 2))
and on (outbound) max by (outbound) (
  xui_balancer_outbound_selected{job="xui-exporter",instance="${instance}",balancer=~"${balancer}",outbound!=""}
)
